/** Totals per month, in cents, keyed "YYYY-MM". */
export function totalsByMonth(rows) {
  const totals = {};
  for (const row of rows) {
    const month = row.date.slice(0, 7);
    totals[month] = (totals[month] || 0) + toCents(row.amount);
  }
  return totals;
}

export function report(text, { month } = {}) {
  const rows = parseCsv(text);
  const totals = totalsByMonth(rows);
  return Object.entries(totals)
    .filter(([m]) => !month || m === month)
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([m, cents]) => `${m}  ${formatCents(cents)}`)
    .join("\n");
}

