import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { readFileSync } from "node:fs";
import { test } from "node:test";
import { report } from "../src/report.js";

test("report filters to a single month", () => {
  const text = readFileSync(new URL("../examples/march.csv", import.meta.url), "utf8");
  assert.equal(report(text, { month: "2026-03" }), "2026-03  USD 125.54");
  assert.equal(report(text, { month: "2026-04" }), "2026-04  USD 15.20");
});

test("cli report --month flag", () => {
  const out = execFileSync(
    "node",
    ["src/cli.js", "report", "examples/march.csv", "--month", "2026-04"],
    { cwd: new URL("..", import.meta.url), encoding: "utf8" },
  );
  assert.equal(out.trim(), "2026-04  USD 15.20");
});

